export const FAQ_TREINO = [
  { q: 'Quantas vezes por semana devo treinar?', tags: 'frequencia dias semana vezes', a: ['Para a saúde, a Organização Mundial da Saúde recomenda fortalecer todos os grandes grupos musculares em 2 ou mais dias por semana, além de 150 a 300 minutos de atividade aeróbica moderada.', 'Para ganhar músculo, o que mais conta é o total de séries da semana: com o mesmo total, dividir em mais ou menos dias muda pouco. Treinar cada grupo pelo menos 2 vezes por semana facilita chegar a esse total e, numa revisão, deu mais ganho de massa do que uma vez só. Escolha a frequência que você consegue manter.'], f: ['oms2020', 'pelland2026', 'schoenfeld2016freq', 'acsm2026'] },
  { q: 'Quantas séries e repetições devo fazer?', tags: 'series repeticoes volume quantas', a: ['Iniciantes evoluem bem com 1 a 3 séries de 8 a 12 repetições por exercício. Para hipertrofia, o alvo é chegar a 10 ou mais séries por grupo muscular por semana; cerca de 4 séries semanais por grupo já dão resultado.', 'Cargas leves ou pesadas (de 30% a 100% do máximo) geram ganho de músculo parecido quando a série é levada perto do limite. Para força máxima, cargas altas (cerca de 80% do máximo ou mais) funcionam melhor.'], f: ['acsm2009', 'acsm2026', 'schoenfeld2017vol', 'schoenfeld2017load', 'schoenfeld2021', 'iversen2021'] },
  { q: 'Preciso treinar até a falha?', tags: 'falha esforco limite rir reserva', a: ['Não. Ir até a falha traz, no máximo, uma vantagem muito pequena para hipertrofia e nenhuma para força, e aumenta o cansaço. Parar com 1 a 3 repetições “na reserva” é suficiente; iniciantes podem deixar 2 a 4.', 'Se quiser usar a falha, prefira a última série de exercícios em máquina, onde é mais seguro.'], f: ['refalo2023', 'acsm2026'] },
  { q: 'Quanto tempo devo descansar entre as séries?', tags: 'descanso intervalo pausa tempo', a: ['Em exercícios pesados e multiarticulares (agachamento, supino, remadas), descanse 2 a 3 minutos. Em exercícios isolados, 1 a 2 minutos.', 'Para hipertrofia, descansar mais de 60 segundos traz um pequeno benefício. Para força, quem já treina costuma render mais com 2 minutos ou mais; iniciantes evoluem bem com 1 a 2 minutos.'], f: ['acsm2009', 'grgic2018', 'singer2024'] },
  { q: 'Quando e quanto aumentar a carga?', tags: 'carga peso aumentar progressao progredir', a: ['Use uma faixa de repetições (por exemplo, 8 a 12). A diretriz é aumentar a carga em 2% a 10% — menos nos músculos pequenos — quando você consegue passar do alvo em 1 ou 2 repetições, em dois treinos seguidos, e então voltar ao início da faixa.', 'O aplicativo aplica essa regra: quando você faz o número mais alto da faixa em todas as séries, em dois treinos seguidos, a sugestão de nova carga aparece no exercício durante o treino.'], f: ['acsm2009', 'aha2024'] },
  { q: 'Dá para dar prioridade a um músculo?', tags: 'foco prioridade priorizar musculo especifico quadriceps triceps biceps gluteos panturrilha especializacao', a: ['Dá. O que mais pesa no ganho de um músculo é o número de séries por semana, com retorno cada vez menor: na análise que reuniu os estudos, quem faz de 5 a 10 séries precisa de cerca de 6 a mais para um ganho perceptível. Subir 20% sobre o que a pessoa já fazia rendeu mais que um volume fixo alto; saltos maiores (de 30% a 120%) não renderam mais em 8 semanas. A referência é de 12 a 20 séries semanais por músculo.'], mais: ['Os outros músculos se mantêm com pouco: cerca de 4 séries por semana. Em adultos jovens, um terço do volume manteve a massa por 32 semanas; depois dos 60 anos é preciso mais (até 2 sessões com 2 a 3 séries por exercício). Por isso o Treinador soma até 6 séries semanais ao músculo escolhido, dentro do teto do seu nível, e não deixa os grandes grupos abaixo de 4 séries (6 a partir dos 60 anos).', 'São até dois músculos por vez. Nenhum estudo comparou priorizar um, dois ou três; a orientação publicada é escolher um ou dois grupos por ciclo. A conta de tempo confirma: cada série leva cerca de 2 minutos, 12 séries da semana ficam reservadas ao resto do corpo e cada prioridade custa 10. Com treinos de 30 minutos, cabe um músculo só.'], f: ['pelland2026', 'iusca2021', 'scarpelli2022', 'barsuhn2025', 'camargo2026', 'bazvalle2022', 'bickel2011', 'spiering2021', 'iversen2021', 'schoenfeld2019vol', 'hackett2013', 'nuckols2025'] },
  { q: 'Perdi um treino. Faço no dia seguinte?', tags: 'perdi faltei nao treinei pulei treino perdido repor compensar dia seguinte juntar dois treinos mesmo dia', a: ['Só se o dia seguinte deixar 48 horas ou mais entre treinos do mesmo músculo. Para ganhar músculo, o que mais conta é o total de séries da semana; em quantos dias você divide muda pouco. Por isso vale passar o treino para um dia livre da mesma semana, quando ele respeita esse descanso.', 'Não junte dois treinos no mesmo dia nem treine forte o mesmo músculo em dias seguidos. Se não houver dia com esse descanso, siga a semana: perder um treino tira pouco, e o treino volta no dia de sempre.', 'Na aba Treinos e no Início, toque em “Não treinei”: o aplicativo procura esse dia para você. Corrida perdida não se repõe. Depois de 2 semanas ou mais sem treinar, valem as regras da volta.'], f: ['pelland2026', 'garber2011', 'acsm2009', 'caterisano2019'] },
  { q: 'De quanto em quanto tempo devo trocar os exercícios?', tags: 'trocar mudar variar exercicios aparelhos aparelho rotina tempo semanas travado estagnado', a: ['Variar os exercícios mais simples ajuda o músculo a crescer por inteiro e deixa o treino menos repetitivo. Mas trocar tudo o tempo todo atrapalha: num estudo, sortear os exercícios a cada treino rendeu um pouco menos de força e de músculo, e fica difícil acompanhar a evolução das cargas.', 'Por isso ficam os exercícios principais e os de várias articulações com peso livre ou com o peso do corpo (agachamento, supinos, remadas, barra fixa), que pedem mais técnica; variam os de máquina e polia e os mais simples. Nenhum estudo definiu de quanto em quanto tempo: o aplicativo segue o ciclo de treino usado na prática, de 4 a 8 semanas. A cada 6 semanas de treino (8 para quem está começando), ele avisa “Hora de variar” e sugere trocar até 2 auxiliares por treino, por outros do mesmo músculo, com os seus aparelhos.', 'Antes disso, só troque o auxiliar que doer ou que ficar 3 treinos sem evoluir (o número de treinos é uma regra do aplicativo). Nos exercícios novos, comece mais leve: movimento novo dá mais dor muscular nos primeiros treinos.'], f: ['bazvalle2019', 'iusca2021', 'acsm2009', 'acsm2026', 'bell2023', 'bell2022'] },
  { q: 'Fiquei um tempo parado. Como voltar?', tags: 'parado pausa voltar volta retorno ferias destreino tempo sem treinar recomecar', a: ['Poucas semanas sem treinar tiram pouca força. A perda aumenta com o tempo parado. Quem já treinou recupera depressa: os núcleos que as fibras musculares ganharam com o treino se mantêm mesmo quando o músculo diminui.', 'Depois de 2 semanas ou mais parado, o consenso das associações americanas de preparadores físicos (CSCCa e NSCA) pede 2 semanas de transição, ou 4 depois de uma pausa longa: cardio com metade do volume na primeira semana e 30% a menos na segunda; na musculação, menos séries por músculo, no máximo 3 treinos do mesmo músculo na primeira semana e descansos mais longos. O aplicativo aplica essas regras sozinho quando você volta.', 'O corte de carga do primeiro treino (de 10% a 50%, conforme o tempo parado) é uma escolha conservadora do aplicativo: o consenso limita o volume e o descanso, não a carga. Você pode mudar a carga a qualquer momento.'], f: ['caterisano2019'] },
  { q: 'Preciso aquecer e alongar antes do treino?', tags: 'aquecimento aquecer alongar alongamento', a: ['Aqueça com séries leves do próprio exercício que vai fazer (aquecimento específico): é o que mais importa. Cinco minutos de cardio leve antes são opcionais.', 'Alongamento parado e longo (mais de 60 segundos por músculo) logo antes do treino reduz a força e a potência em 4 a 7,5%; com até 60 segundos, a perda é de 1 a 2%. Se o objetivo é flexibilidade, alongue depois do treino ou em outro horário.'], f: ['iversen2021', 'chaabene2019'] },
  { q: 'Fazer cardio atrapalha o ganho de músculo?', tags: 'cardio aerobico esteira interferencia musculo', a: ['Não. Combinar cardio e musculação não prejudica o ganho de massa nem a força máxima. Só a força explosiva pode ser um pouco reduzida, principalmente quando os dois são feitos na mesma sessão.', 'Para a saúde, some 150 a 300 minutos de atividade aeróbica moderada por semana.'], f: ['schumann2022', 'oms2020'] },
  { q: 'Corro e faço musculação: uma atrapalha a outra?', tags: 'corrida correr musculacao junto combinar interferencia prioridade foco equilibrio pernas vespera', a: ['Em quem treina por saúde ou lazer, juntar as duas não reduz o ganho de massa nem a força máxima. Em pessoas já treinadas, a força das pernas cresce menos quando corrida e musculação ficam na mesma sessão; com mais de 2 horas entre elas, a diferença quase some.', 'O contrário pesa mais: o treino de pernas deixa a corrida pior nas horas seguintes, e em quem está começando na musculação isso dura pelo menos 48 horas. Por isso, quando você dá prioridade à corrida ou pede equilíbrio, o Treinador põe os treinos de pernas a 24 horas ou mais da corrida forte e tira o cardio do plano, porque a corrida já conta.', 'No mesmo dia, deixe mais de 3 horas entre as duas; de 6 a 24 horas é melhor. Na mesma sessão, fazer a musculação antes rende mais força nas pernas.'], f: ['schumann2022', 'petre2021', 'blagrove2018', 'doma2017', 'methenitis2018', 'eddens2018'] },
  { q: 'Quem corre precisa de fortalecimento?', tags: 'corrida correr fortalecimento fortalecer forca corredor lesao economia panturrilha quadril core casa academia', a: ['Ajuda no desempenho: 2 a 3 treinos de força por semana, por 6 a 14 semanas, melhoram a economia de corrida em 2 a 8%, sem aumentar o peso do corpo e sem precisar ir até a falha. Um treino por semana mantém o ganho; parando, ele some em cerca de 6 semanas.', 'Para evitar lesões, a evidência é mais fraca: um programa de quadril e core com acompanhamento de fisioterapeuta reduziu as lesões por sobrecarga em corredores iniciantes, mas programas feitos por conta própria, por vídeo, não mostraram efeito. Fortalecer não substitui aumentar a corrida aos poucos.', 'Se você já faz musculação: mantenha no treino de pernas agachamento, quadril, panturrilha, abdutores do quadril, um exercício em um pé só e core, longe da corrida forte. A panturrilha entra porque o sóleo é o músculo que mais sustenta o corpo a cada passada.', 'Se você não faz musculação: 2 treinos curtos por semana, em casa ou na academia, com 2 a 3 séries de 8 a 12 repetições. Comece com carga leve para aprender os movimentos e só depois aumente.'], f: ['blagrove2018', 'leppanen2024', 'toresdahl2020', 'wu2024', 'ronnestad2014', 'hamner2013'] },
  { q: 'Qual é o melhor treino para emagrecer?', tags: 'emagrecer perder gordura peso queimar', a: ['O que faz emagrecer é gastar mais energia do que se consome, e isso depende principalmente da alimentação. A musculação protege os músculos durante o emagrecimento; o cardio aumenta o gasto.', 'Com 150 a 200 minutos semanais de atividade aeróbica moderada, a perda de peso é modesta (cerca de 2 a 3 kg); perda maior pede mais de 225 minutos por semana ou dieta junto. A musculação quase não muda o peso, mas limita a perda de massa magra.'], f: ['swift2014', 'oppert2021', 'oms2020'] },
  { q: 'O que é um “deload” e quando fazer?', tags: 'deload descanso semana leve cansaco', a: ['É uma semana mais leve, com menos séries ou menos carga, para recuperar. Treinadores costumam planejá-la a cada 4 a 8 semanas, ou quando aparece cansaço acumulado, do corpo ou da cabeça.', 'Não precisa ter data fixa: também pode ser feito só quando o cansaço aparecer. Na prática: faça menos séries, menos repetições ou menos dias por cerca de uma semana e depois retome.'], f: ['bell2023'] },
  { q: 'Tenho mais de 60 anos. Posso fazer musculação?', tags: 'idoso idosos idade 60 anos terceira', a: ['Sim, e é recomendado: a musculação melhora força, equilíbrio, independência e saúde dos ossos. O programa indicado tem 2 a 3 treinos por semana, 1 a 3 séries de 8 a 12 repetições, começando leve e progredindo aos poucos, sem necessidade de ir até a falha.', 'A partir dos 65 anos, a OMS também recomenda atividades que treinam equilíbrio e força em 3 ou mais dias por semana, para prevenir quedas. Quem tem pressão alta descontrolada deve tratar antes de treinar.'], f: ['fragala2019', 'oms2020', 'acsm2009'] },
  { q: 'Tenho pressão alta. Posso treinar?', tags: 'pressao alta hipertensao coracao', a: ['Com a pressão controlada e liberação médica, sim: a musculação ajuda a reduzir a pressão. Use cargas leves a moderadas com mais repetições (10 a 15), descanse bem entre as séries e nunca prenda a respiração — solte o ar na fase de esforço. Não treine com a pressão acima de 160 por 105 mmHg.', 'Pare e procure atendimento se sentir dor ou pressão no peito, tontura, falta de ar fora do normal ou palpitações.'], f: ['aha2024', 'whitfield2017', 'sbc_has2020', 'esc2020'] },
  { q: 'Tenho diabetes. Posso fazer musculação?', tags: 'diabetes glicemia glicose insulina acucar no sangue hipoglicemia', a: ['Pode, e é recomendado: a musculação ajuda a controlar a glicose. As diretrizes indicam 2 a 3 sessões por semana em dias não seguidos, com 8 a 10 exercícios e 1 a 3 séries de 10 a 15 repetições, progredindo para 8 a 10. Por isso o plano do Treinador fica em 8 repetições ou mais, com a força em dias alternados; antes de treinos mais pesados, peça liberação médica.', 'Se você usa insulina ou sulfonilureia, meça a glicemia antes de treinar: abaixo de 90 mg/dL, coma 15 a 30 g de carboidrato de ação rápida e tenha mais à mão. Acima de 250 mg/dL com cetonas, não treine.', 'Com retinopatia ou doença nos rins, evite carga máxima, prender a respiração e ficar de cabeça baixa, e peça orientação do seu médico. Com perda de sensibilidade nos pés, olhe os pés todos os dias e use calçado adequado.'], f: ['colberg2016', 'kanaley2022', 'sbd2023', 'whitfield2017'] },
  { q: 'Estou grávida. Posso continuar treinando?', tags: 'gravida gestante gravidez gestacao', a: ['Em gestações sem complicações, o exercício é seguro e recomendado: pelo menos 150 minutos semanais de atividade moderada, com fortalecimento muscular. É indispensável a liberação do obstetra.', 'Evite esportes de contato e risco de queda. Interrompa e procure o médico em caso de sangramento, contrações, perda de líquido, tontura ou dor no peito.'], f: ['acog804', 'oms2020'] },
  { q: 'Sinto dor nas costas. Devo parar de treinar?', tags: 'dor costas lombar coluna', a: ['Para dor lombar crônica, o exercício é tratamento: reduz a dor de forma clinicamente importante e melhora um pouco a função. A revisão não aponta um tipo de exercício melhor nem uma lista de exercícios “proibidos”; as diretrizes pedem programas individualizados.', 'Dor forte, que desce para a perna, com formigamento ou perda de força precisa de avaliação médica antes de treinar.'], f: ['hayden2021', 'verhagen2016'] },
  { q: 'Tenho dor no joelho. Quais exercícios adaptar?', tags: 'joelho dor patela agachamento extensora', a: ['Na dor na frente do joelho (patelofemoral), a carga sobre a articulação é menor no agachamento feito até cerca de 45° de flexão e na cadeira extensora entre 90° e 45°. Trabalhar nessas faixas costuma permitir treinar sem piorar a dor.', 'Fortalecer quadríceps e glúteos faz parte do tratamento. Se a dor persistir ou houver inchaço, procure um ortopedista ou fisioterapeuta.'], f: ['jospt2014'] },
  { q: 'Como proteger os ombros na musculação?', tags: 'ombro ombros lesao dor proteger', a: ['O ombro é uma das regiões mais lesionadas na musculação (até cerca de um terço das lesões). Como cuidado, evite puxadas e desenvolvimentos por trás da nuca e, na remada alta, não suba os cotovelos acima da linha dos ombros.', 'Inclua exercícios para a parte de trás dos ombros, para os músculos da escápula e para o manguito rotador (crucifixo inverso, face pull, rotação externa).'], f: ['bonilla2022', 'schoenfeld2011upright'] },
  { q: 'Estou com dor muscular depois do treino. Posso treinar?', tags: 'dor muscular dolorido tardia doms depois treino dia seguinte', a: ['Pode. A dor muscular tardia aparece de 12 a 24 horas depois de um esforço a que o corpo não está acostumado, é mais forte entre 24 e 72 horas e some em 5 a 7 dias. A orientação é evitar esforço intenso no músculo dolorido e, nos dias seguintes, treiná-lo mais leve ou treinar outras partes do corpo: a dor some antes de a força voltar ao normal.', 'Os estudos não dão um número de dor a partir do qual reduzir; por isso o Treinador pede treino mais leve nesse músculo enquanto ele estiver dolorido. Massagem é o que mais reduz a dor; alongar depois do exercício não reduz a dor nos dias seguintes. Repetir o mesmo treino protege: a dor diminui nas semanas seguintes. Dor que passa de 7 dias, ou que veio de repente durante o esforço, não é a dor comum do treino.'], f: ['hody2019', 'dupuy2018', 'afonso2021'] },
  { q: 'Sinto dor numa articulação ou num tendão. Paro de treinar?', tags: 'dor articulacao tendao tendinite tendinopatia joelho ombro cotovelo tornozelo treinar com dor', a: ['Em geral, não. Nos estudos com dor no tendão de Aquiles, no ombro e na artrose de quadril e joelho, continuar treinando não atrapalhou a recuperação com estas regras: dor até 5 em 10 durante o exercício, voltando ao normal até a manhã seguinte e sem aumentar de uma semana para outra. De 0 a 2 é zona segura; de 3 a 5, aceitável; acima de 5, risco alto.', 'Na prática: baixe a carga e a amplitude até a faixa que não piora a dor, troque o exercício por um que poupe a região e continue treinando o resto do corpo. Tendão irritado pede menos carga e um ou dois dias entre os esforços mais fortes, não repouso total.'], mais: ['Esses estudos tinham fisioterapeuta acompanhando, e no tendão do joelho o limite usado foi 3 em 10. Por isso o Treinador aceita até 5 só no ombro, no tendão de Aquiles e no quadril de quem já treina. Nas outras regiões, e sempre para iniciantes, 60 anos ou mais, menores de 18 e gestantes, o teto é 3: acima dele, os exercícios que sobrecarregam a região saem do treino.', 'O lado do corpo e o momento em que a dor aparece (durante ou depois do treino) ficam só registrados: o limite é o mesmo nos dois casos. Dor em repouso é sinal de alerta.', 'Dor forte ou de alerta não some sozinha do plano: depois de 3 semanas sem atualização, o Treinador pergunta como ela está. Se melhorou, a região volta com menos carga e amplitude por 2 semanas.'], f: ['silbernagel2007', 'silbernagel2020', 'ageberg2010', 'holmgren2012', 'larsson2019', 'breda2021', 'bateman2021', 'jorgensen2018', 'raulline2025', 'smith2017', 'cook2009', 'fragala2019', 'dubois2020', 'caterisano2019'] },
  { q: 'Quando a dor pede médico ou fisioterapeuta?', tags: 'dor forte alerta medico fisioterapeuta lesao fisgada estalo inchaco repouso noite avaliacao', a: ['Procure avaliação antes de treinar a região se a dor é forte, veio de repente com fisgada ou estalo, vem com inchaço ou perda de força, ou aparece em repouso ou à noite. Pelo modelo de monitoramento da dor, acima de 5 em 10 já é faixa de risco alto. Nas costas, procure atendimento logo se houver dormência entre as pernas, dificuldade para urinar, febre, perda de peso sem explicação, histórico de câncer ou trauma importante. Na gestação: dor no abdômen, dor ou inchaço na panturrilha, sangramento ou tontura.', 'Depois de uma lesão aguda, a orientação atual é proteger a região por 1 a 3 dias e voltar ao movimento aos poucos, com a dor como guia; repouso prolongado atrapalha a recuperação.', 'Dor de 7 ou mais em 10 é classificada como intensa na escala original, feita em dor de câncer; em dor crônica de músculos e articulações, o corte estimado foi 8. O aplicativo usa 7, o mais cauteloso, como sinal de alerta. Ele não faz diagnóstico: na dúvida, procure avaliação.'], f: ['verhagen2016', 'dubois2020', 'acog804', 'ageberg2010', 'boonstra2016', 'serlin1995'] },
  { q: 'Quais exercícios o Treinador não escolhe sozinho?', tags: 'seguranca perigoso perigosos risco lesao evitar salto barra supervisao proibido', a: ['Como aqui não há um profissional ao lado, o Treinador nunca escolhe sozinho: saltos e exercícios de potência, que pedem base de força e técnica já dominada; o treino intervalado de alta intensidade, cuja segurança só foi estudada com supervisão; o bom-dia com barra, que carrega a lombar tanto quanto o levantamento terra; a remada sob a mesa, em que a mesa pode virar sobre a pessoa; e o agachamento hack invertido e o articulado de frente, que não têm estudo nem guia de entidade profissional. Eles continuam no catálogo para quem quiser incluir por conta própria.'], mais: ['A musculação é segura para adultos saudáveis e o risco de lesão é baixo. As lesões aparecem mais em quem tem pouca experiência, com carga pesada, posição desfavorável ou técnica errada; das que chegam ao pronto-socorro, a maior parte envolve pesos livres, e a queda do peso sobre a pessoa é uma das causas principais.', 'Por perfil: corrida e saltos só para quem já treina, sem dose conservadora e com IMC abaixo de 30 (acima disso, a diretriz europeia considera razoável limitar o exercício de impacto em grande volume). Barra livre em exercícios compostos fica fora para gestantes (peso livre é menos indicado pelo equilíbrio), menores de 18 (as lesões graves acontecem sem supervisão), pressão alta e coração (evitar levantamento pesado e prender a respiração) e 60 anos ou mais (máquinas são o ponto de partida). Bola suíça, fitas de suspensão e exercícios em um pé só ficam fora para 60 anos ou mais e gestantes, pelo risco de queda.', 'Com pressão alta, coração, gestação ou triagem positiva, ficam fora também os exercícios em que é fácil prender a respiração e os de cabeça abaixo do coração: as diretrizes mandam evitar a manobra de Valsalva, e as posturas invertidas elevam a pressão e são contraindicadas na hipertensão. A diretriz brasileira orienta não treinar com a pressão acima de 160 por 105 mmHg.'], f: ['acsm2026', 'keogh2017', 'gray2015', 'davies2015', 'wewege2018', 'oppert2021', 'schellenberg2013', 'esc2020', 'sbc_gestacao2021', 'faigenbaum2010', 'fragala2019', 'izquierdo2021', 'sbc_reab2020', 'sbc_has2020', 'joshi2024'] },
  { q: 'A amplitude do movimento importa?', tags: 'amplitude completa parcial movimento', a: ['Sim, principalmente nas pernas: usar a amplitude completa do movimento dá mais ganho muscular do que repetições parciais. Nos braços, os estudos são poucos e não concordam. Use a maior amplitude que você controla sem dor.'], f: ['schoenfeld2020rom'] },
  { q: 'Adolescente pode fazer musculação?', tags: 'adolescente jovem crianca menor idade', a: ['Pode, e traz benefícios, desde que com supervisão de um profissional, técnica correta e cargas adequadas. A prioridade é aprender os movimentos; aumentar a carga vem depois.', 'A recomendação é de 2 a 3 treinos de força por semana, em dias não seguidos: é assim que o Treinador monta o plano de quem tem menos de 18 anos, com cardio nos outros dias.'], f: ['faigenbaum2009', 'lloyd2014', 'oms2020'] },
  { q: 'Quando devo procurar um médico antes de começar?', tags: 'medico liberacao exame avaliacao comecar', a: ['Quem não tem doenças nem sintomas pode começar com intensidade leve a moderada. Procure liberação médica antes se você é sedentário e tem doença do coração, diabetes ou doença renal, ou se apresenta qualquer sintoma como dor no peito, falta de ar, tontura, desmaio ou palpitações.'], f: ['whitfield2017'] },
];

export const FAQ_NUTRI = [
  { q: 'Quanta proteína preciso por dia?', tags: 'proteina quanto gramas dia', a: ['Para quem treina, a recomendação é de 1,4 a 2,0 g de proteína por quilo de peso por dia. O ganho de massa se estabiliza por volta de 1,6 g/kg, com alguma margem até 2,2 g/kg.', 'Em dieta para emagrecer, vale ficar na parte alta da faixa para proteger os músculos. Pessoas acima de 65 anos precisam de pelo menos 1,0 a 1,2 g/kg.', 'Quem ainda não treina precisa de menos: o mínimo recomendado para adultos (RDA) é 0,8 g/kg; numa dieta para emagrecer, a necessidade sobe para pelo menos 1,2 g/kg, para proteger os músculos. Acima do peso, a conta usa o peso que a pessoa teria com IMC 25, porque a gordura a mais não aumenta a necessidade de proteína.', 'Quem tem doença nos rins não deve aumentar a proteína sem orientação médica: a diretriz para a doença renal crônica sugere 0,8 g/kg e manda evitar mais de 1,3 g/kg.'], f: ['jager2017', 'morton2018', 'helms2014', 'weijs2025', 'dri_canada', 'deutz2014', 'kdigo2024'] },
  { q: 'Como dividir a proteína nas refeições?', tags: 'proteina refeicao dividir distribuir', a: ['Divida ao longo do dia, a cada 3 a 4 horas, com 20 a 40 g de proteína por refeição (cerca de 0,25 a 0,4 g por quilo de peso). Quatro refeições com 0,4 g/kg já somam 1,6 g/kg no dia. Para ter uma ideia: 100 g de peito de frango grelhado têm cerca de 32 g de proteína; 3 ovos, cerca de 20 g.'], f: ['jager2017', 'schoenfeld2018'] },
  { q: 'O que comer antes do treino?', tags: 'pre treino antes comer', a: ['Uma refeição com carboidrato e um pouco de proteína, de 1 a 4 horas antes: quanto mais perto do treino, menor e mais leve. A recomendação para atletas é de 1 a 4 g de carboidrato por quilo nesse período; para um treino comum de musculação, a parte baixa da faixa basta.', 'Exemplos: banana com iogurte e aveia; pão com ovos; ou o próprio almoço, 2 a 3 horas antes.'], f: ['thomas2016', 'kerksick2017'] },
  { q: 'O que comer depois do treino?', tags: 'pos treino depois comer janela', a: ['Faça uma refeição com 20 a 40 g de proteína e carboidrato nas duas horas seguintes. A chamada “janela anabólica” é mais larga do que se pensava: se você comeu bem antes do treino, não há pressa.', 'Repor carboidrato rapidamente só é essencial para quem vai treinar de novo em poucas horas.'], f: ['kerksick2017', 'aragon2013'] },
  { q: 'Posso treinar em jejum?', tags: 'jejum treinar manha sem comer', a: ['Pode, se você se sente bem, mas não há vantagem para perder gordura quando as calorias do dia são as mesmas. Se sentir fraqueza ou tontura, coma algo leve antes. Depois do treino em jejum, faça logo uma refeição com proteína.', 'Pessoas com diabetes não devem treinar em jejum sem orientação médica.'], f: ['schoenfeld2014', 'aragon2013'] },
  { q: 'Quantas calorias devo comer para emagrecer?', tags: 'calorias emagrecer deficit dieta quantas', a: ['Uma redução de 500 a 750 kcal por dia em relação ao gasto é a referência das diretrizes. O ritmo recomendado é perder de 0,5% a 1% do peso por semana: mais devagar preserva melhor os músculos.', 'Dietas muito restritas (abaixo de cerca de 1.200 kcal para mulheres e 1.500 kcal para homens) só devem ser feitas com acompanhamento profissional.', 'Perder peso é indicado com IMC de 30 ou mais, ou de 25 a 29,9 com fator de risco, como pressão alta ou diabetes. Com IMC abaixo de 25, a orientação das diretrizes é não ganhar peso. Depois dos 65 anos, sem obesidade, dieta para emagrecer não é indicada: perde-se músculo junto.', 'Cada 7.700 kcal a menos equivalem a cerca de 1 kg de gordura (500 kcal por dia, perto de meio quilo por semana). É uma conta teórica: o corpo se adapta e a perda real costuma ser menor. Acompanhe o peso por 2 a 3 semanas e ajuste.'], f: ['jensen2013', 'volkert2022', 'helms2014'] },
  { q: 'Como comer para ganhar massa muscular?', tags: 'ganhar massa musculo bulking superavit', a: ['Coma um pouco acima do seu gasto: cerca de 10% a 20% a mais, ou 350 a 500 kcal por dia, com proteína de 1,6 a 2,2 g/kg. O ganho esperado é de 0,25% a 0,5% do peso por semana; mais rápido que isso, boa parte tende a ser gordura.', 'Sem treino de força bem feito, o excedente de calorias vira gordura.'], f: ['iraki2019', 'slater2019', 'morton2018'] },
  { q: 'Low-carb ou low-fat: qual dieta emagrece mais?', tags: 'low carb low fat dieta carboidrato gordura melhor', a: ['Em um estudo de 12 meses com 609 adultos, os dois grupos emagreceram de forma parecida: cerca de 5,3 kg com pouca gordura e 6,0 kg com pouco carboidrato, uma diferença que não foi significativa. Nem o perfil genético nem a resposta de insulina de cada pessoa indicaram qual das duas dietas funcionaria melhor.', 'Escolha o padrão que combina com a sua rotina e as suas preferências.'], f: ['gardner2018'] },
  { q: 'Jejum intermitente funciona?', tags: 'jejum intermitente funciona emagrece', a: ['Funciona tanto quanto reduzir calorias todos os dias: as revisões de estudos mostram perda de peso equivalente. É uma opção, não um método superior.', 'Os estudos foram feitos com adultos, quase sempre sem diabetes. Não é indicado sem acompanhamento para pessoas com diabetes, gestantes, adolescentes ou quem tem histórico de transtorno alimentar.'], f: ['cioffi2018'] },
  { q: 'Quanta água devo beber?', tags: 'agua hidratacao beber litros', a: ['Como referência, a ingestão total de água (bebidas e alimentos) é de cerca de 2,0 litros por dia para mulheres e 2,5 litros para homens. Cerca de 80% disso vem do que se bebe: 1,6 litro para mulheres e 2,0 litros para homens. É essa a referência que o aplicativo mostra.', 'Esses valores valem para clima ameno e atividade moderada: no calor e nos dias de treino você precisa de mais. Beba conforme a sede; beber muito além dela também faz mal.', 'No treino: beba de 5 a 10 mL por quilo nas 2 a 4 horas antes, vá bebendo durante e reponha depois. A cor da urina é um bom guia: clara indica boa hidratação.'], f: ['efsa2017', 'volkert2022', 'thomas2016'] },
  { q: 'Como o aplicativo sabe quais alimentos são baratos ou caros?', tags: 'preco barato caro custo economia dinheiro mais baratos', a: ['Cada alimento tem uma faixa — barato ($), médio ($$) ou caro ($$$) — calculada com preços pesquisados entre o fim de 2025 e novembro de 2026: Procons, Dieese, governos do Paraná e do Rio Grande do Norte, universidades e, para o que essas pesquisas não cobrem, as prateleiras de duas redes de supermercados.', 'A conta considera o preço do quilo pronto para comer e o custo da porção; nas carnes, ovos, leite e feijões, vale o custo de cada 100 g de proteína. Por isso frango, ovos, feijão e sardinha saem baratos, e filé-mignon, salmão e iogurte, caros.', 'Preço muda com a cidade e a época do ano: a faixa é uma referência, não o preço da sua loja. Todos os alimentos têm preço pesquisado. Em poucos (jabuticaba, corvina, ovo de codorna, caldo de cana, soja e whey), a única fonte foi uma notícia ou um indicador de mercado; nos pratos prontos, como feijoada e estrogonofe, o custo é a soma dos ingredientes.'], f: ['precos2026'] },
  { q: 'O diário de alimentação é exato?', tags: 'diario registro anotar comi calorias contar exato erro meta passou faltam', a: ['Não, e não precisa ser. Quem anota o que come costuma registrar menos do que comeu: nos estudos que mediram o gasto de verdade, o registro ficou de 11% a 41% abaixo. Além disso, as calorias de cada alimento são médias de tabela.', 'Use o diário para enxergar o padrão da semana, não para fechar a conta de um dia. Passar 250 kcal da meta em um dia equivale, na conta teórica, a cerca de 30 g de gordura.', 'Com histórico de transtorno alimentar, contar calorias pode piorar os sintomas: nesse caso o aplicativo não oferece o diário. Para menores de 18 anos, ele mostra só os alimentos, sem calorias: o uso desses aplicativos na adolescência foi associado a mais comportamentos de transtorno alimentar no início da vida adulta.'], f: ['burrows2019', 'taco', 'helms2014', 'eikey2021', 'moody2025'] },
  { q: 'Posso montar o cardápio só com o que tenho em casa?', tags: 'casa despensa geladeira tenho alimentos lista cardapio', a: ['Pode. Em “Um dia de exemplo”, escolha “O que tenho em casa” e marque os alimentos. O cardápio passa a usar só esses itens, nas quantidades que mais se aproximam das suas metas de calorias e proteína.', 'Quando faltar um grupo importante — por exemplo, uma fonte de proteína — o aplicativo avisa e sugere a opção mais barata para completar. Havendo escolha, os ultraprocessados ficam de fora.'], f: ['taco', 'guia2014'] },
  { q: 'O que comer e beber durante a corrida?', tags: 'corrida correr durante gel carboidrato isotonico agua hidratacao prova maratona', a: ['Depende da duração. Até 45 minutos, só água se tiver sede. De 45 a 75 minutos, carboidrato é opcional. De 75 minutos a 2 horas e meia, de 30 a 60 g de carboidrato por hora. Acima disso, até 90 g por hora, misturando fontes (glicose e frutose), se você treinou isso.', 'Um gel tem de 20 a 30 g de carboidrato; 30 g são também 2 bananas-prata ou 1 bananada e meia. Teste tudo nos treinos longos, nunca no dia da prova.', 'Beba conforme a sede: para a maioria, isso dá de 400 a 800 mL por hora. Beber além dela dilui o sódio do sangue (hiponatremia), o que é perigoso, e bebida esportiva ou sal não evitam isso em quem bebe demais.'], f: ['thomas2016', 'jeukendrup2014', 'ais_gel', 'hewbutler2017'] },
  { q: 'Preciso fazer carga de carboidrato antes da prova?', tags: 'carga carboidrato prova corrida maratona meia vespera macarrao', a: ['Só em provas com mais de 90 minutos, como a meia maratona para a maioria das pessoas e a maratona. Nas 36 a 48 horas anteriores, coma de 10 a 12 g de carboidrato por quilo por dia, treinando menos e com pouca fibra e gordura.', 'Em provas de 5 e 10 km, basta comer normalmente na véspera, com carboidrato em todas as refeições, e fazer um café da manhã leve, de 2 a 3 horas antes da largada.'], f: ['thomas2016'] },
  { q: 'Creatina funciona? É segura?', tags: 'creatina suplemento funciona seguro', a: ['É o suplemento com mais evidência para força e massa muscular. A dose estudada é de 3 a 5 g por dia de creatina monoidratada, todos os dias, e é considerada segura para adultos saudáveis.', 'Não use sem orientação se você tem doença nos rins, está grávida ou amamentando, ou tem menos de 18 anos. Este aplicativo não prescreve suplementos: converse com um nutricionista.'], f: ['kreider2017'] },
  { q: 'Cafeína melhora o treino?', tags: 'cafeina cafe pre treino estimulante', a: ['Sim: os estudos mostram melhora do desempenho com 3 a 6 mg por quilo de peso, cerca de 60 minutos antes. Doses muito altas trazem mais efeitos colaterais sem ganho extra.', 'Por segurança, fique na parte baixa da faixa: a autoridade europeia de segurança dos alimentos (EFSA) considera seguros para adultos até 200 mg por vez (cerca de 3 mg por quilo) e 400 mg por dia; gestantes, até 200 mg por dia. Evite se tem pressão alta, arritmia ou ansiedade, e à noite, para não prejudicar o sono.'], f: ['guest2021', 'efsa2015'] },
  { q: 'Preciso tomar whey protein?', tags: 'whey proteina suplemento po', a: ['Não é obrigatório. Whey é apenas uma forma prática de proteína: conta na meta diária como qualquer alimento. Se você atinge a proteína do dia com comida, não precisa.'], f: ['jager2017'] },
  { q: 'Devo tomar pré-treino?', tags: 'pre treino pre-treino pronto po estimulante energia foco pump', a: ['Não precisa. O que tem efeito comprovado nele é a cafeína, que também vem do café. Os outros ingredientes muitas vezes estão em dose baixa demais, ou a quantidade nem aparece no rótulo.', 'Se for usar: só adulto saudável, uma dose com até 200 mg de cafeína, sem passar de 400 mg no dia somando o café, e longe da hora de dormir. Menores de 18 anos, gestantes, lactantes e quem tem pressão alta ou doença do coração: não.'], f: ['harty2018', 'guest2021', 'efsa2015', 'anvisa_in28', 'gardiner2023'] },
  { q: 'Pré-treino faz mal?', tags: 'pre treino faz mal perigoso efeito colateral palpitacao coracao taquicardia formigamento', a: ['Em adultos saudáveis, na dose do rótulo, os estudos curtos não acharam dano. Mas, numa pesquisa com 872 usuários, 54% contaram algum efeito: reação na pele, coração acelerado, enjoo ou tontura.', 'O risco cresce com duas doses, com outros produtos com cafeína e com estimulantes como DMAA, sinefrina e ioimbina. Pare se tiver palpitação, tontura, ansiedade ou insônia; dor no peito, falta de ar ou desmaio pedem atendimento na hora.'], f: ['harty2018', 'jagim2019', 'bella2025', 'porrill2024', 'whitfield2017'] },
  { q: 'Posso tomar pré-treino e café no mesmo dia?', tags: 'pre treino cafe energetico somar juntar cafeina limite dia xicara', a: ['Pode, se a soma couber. Para adultos saudáveis, a autoridade europeia de segurança dos alimentos (EFSA) considera seguros até 200 mg de cafeína de uma vez e 400 mg no dia, de todas as fontes. Uma xícara de café tem cerca de 100 mg; muitos pré-treinos têm de 250 a 400 mg por dose.', 'Conte também chá-mate, chá preto, refrigerante de cola e energético. Dose acima de 200 mg: não use.'], f: ['efsa2015', 'jagim2019', 'gardiner2023'] },
  { q: 'BCAA funciona?', tags: 'bcaa aminoacidos leucina valina isoleucina', a: ['Para quem já come a proteína do dia, não acrescenta: a comida e o whey já trazem os BCAA. Num estudo, o BCAA sozinho estimulou o músculo pela metade do que o whey com a mesma quantidade de BCAA.', 'O Instituto Australiano do Esporte o classifica como sem evidência de benefício para atletas. Alguns estudos mostram um pouco menos de dor muscular depois de treino pesado, mas os resultados são mistos.'], f: ['kerksick2018', 'ais_abcd'] },
  { q: 'Termogênico emagrece?', tags: 'termogenico queimador gordura emagrecer fat burner cha verde cromo cla', a: ['Quase nada. O consenso do Comitê Olímpico Internacional diz que falta prova para a grande maioria dos “queimadores de gordura”: chá verde e CLA tiveram efeito pequeno ou trivial, e o cromo, nenhum.', 'Muitos são cafeína com outros estimulantes, e alguns trazem substâncias proibidas, como o DMAA. O que emagrece é comer menos do que se gasta, com treino; nisso, mais proteína na dieta ajuda, e cápsula não.'], f: ['maughan2018', 'anvisa2013', 'bfr2012'] },
  { q: 'Suplemento pode dar doping?', tags: 'doping antidoping contaminacao exame atleta selo certificado terceira parte', a: ['Pode. Num estudo com mais de 600 produtos do mundo todo, cerca de 15% tinham hormônios que não estavam no rótulo, e até vitaminas já foram achadas contaminadas.', 'Se você faz exame antidoping, use só o que precisa e prefira produto com certificação de terceira parte, que testa os lotes. Mesmo assim, não há garantia total.'], f: ['maughan2018', 'harty2018', 'ais_abcd'] },
  { q: 'Preciso tomar vitamina D ou ferro?', tags: 'vitamina d ferro anemia exame multivitaminico vitaminas minerais', a: ['Só se o exame mostrar falta. O consenso do Comitê Olímpico Internacional não recomenda suplementar vitaminas e minerais sem avaliação, e ferro em dose alta só deve ser usado com falta de ferro confirmada.', 'Quem define a dose é o médico. A exceção conhecida é a vitamina B12, que veganos precisam suplementar.'], f: ['maughan2018', 'ais_abcd', 'rogerson2017'] },
  { q: 'Beta-alanina dá formigamento. É perigoso?', tags: 'beta alanina formigamento coceira pre treino carnosina', a: ['O formigamento é o único efeito colateral relatado e passa sozinho; doses menores e divididas o diminuem. A beta-alanina ajuda em esforços fortes de 1 a 4 minutos; se melhora a força, ainda não se sabe.', 'No Brasil, o rótulo pode indicar no máximo 2 g por dia, em doses de até 300 mg, com 2 horas entre elas.'], f: ['trexler2015', 'maughan2018', 'anvisa_in28'] },
  { q: 'E anabolizante, SARM ou “testosterona natural”?', tags: 'anabolizante esteroide testosterona hormonio sarm tribulus bomba ciclo', a: ['Anabolizante e SARM: nunca. No Brasil, o Conselho Federal de Medicina proíbe o médico de receitar anabolizante para estética ou desempenho e de receitar SARM. Produtos vendidos como suplemento já foram achados com esteroides que causam dano ao fígado e alterações de comportamento.', 'Os de “testosterona natural”, como o tribulus, não mudaram força nem massa nos estudos.'], f: ['cfm2333', 'maughan2018', 'kerksick2018', 'ais_abcd'] },
  { q: 'O que é uma alimentação saudável, segundo o Guia Alimentar?', tags: 'saudavel guia alimentar ultraprocessados comida de verdade', a: ['A regra de ouro do Guia Alimentar para a População Brasileira: prefira sempre alimentos in natura ou minimamente processados e preparações culinárias a alimentos ultraprocessados.', 'Na prática: arroz, feijão, carnes, ovos, frutas, verduras e legumes como base; óleos, sal e açúcar em pequenas quantidades; limitar processados (queijos, pães, conservas); evitar ultraprocessados (refrigerantes, biscoitos recheados, salgadinhos, embutidos).'], f: ['guia2014'] },
  { q: 'Quanto de sal, açúcar e fibras por dia?', tags: 'sal sodio acucar fibras limite', a: ['Sal: menos de 5 g por dia (2 g de sódio). Açúcares livres (os adicionados, mais os do mel e dos sucos): menos de 10% das calorias, de preferência menos de 5%. Fibras: pelo menos 25 g por dia, com pelo menos 400 g de frutas, verduras e legumes.', 'Gorduras: até 30% das calorias, com gordura saturada abaixo de 10%.'], f: ['oms_dieta'] },
  { q: 'Dieta vegetariana ou vegana atrapalha os resultados?', tags: 'vegetariano vegano vegetariana vegana planta', a: ['Não precisa atrapalhar. Com um bom planejamento dos alimentos e os suplementos certos, uma dieta vegana atende às necessidades de quem treina. Mire a parte alta da faixa de proteína (1,4 a 2,0 g/kg) e combine leguminosas (feijão, lentilha, grão-de-bico, soja) com cereais todos os dias.', 'Veganos precisam suplementar vitamina B12 e dar atenção a ferro, cálcio, zinco, iodo, vitamina D e ômega-3.'], f: ['rogerson2017', 'jager2017'] },
  { q: 'Como o aplicativo calcula as minhas calorias?', tags: 'calculo calorias formula gasto tmb', a: ['O gasto em repouso é estimado pela equação de Mifflin-St Jeor, uma das mais usadas. Nos estudos que a compararam com o gasto medido, ela acertou dentro de 10% em cerca de 45% a 75% das pessoas, conforme o grupo, e errou para mais depois de uma dieta.', 'Esse valor é multiplicado pelo nível de atividade física do relatório FAO/OMS/UNU: 1,45 para quem passa o dia sentado, 1,60 para quem fica em pé ou caminha parte do dia, 1,75 para trabalho em movimento e 1,90 para trabalho braçal pesado. O treino soma até 0,19 (uma hora de exercício por dia vale 0,20), e o total nunca passa de 2,40.', 'É uma estimativa: acompanhe o seu peso por 2 a 3 semanas e ajuste a quantidade de comida conforme o resultado.'], f: ['ruiz2011', 'amaro2019', 'fao2004'] },
  { q: 'O aplicativo substitui um nutricionista?', tags: 'nutricionista substitui consulta prescricao', a: ['Não. O que você vê aqui é orientação educativa baseada em diretrizes públicas. No Brasil, a assistência dietoterápica, com a prescrição de dietas, é atividade privativa do nutricionista. Procure um profissional para um plano individualizado, especialmente se tiver alguma doença, estiver grávida ou amamentando, ou tiver menos de 18 anos.'], f: ['lei8234'] },
];

export function buscarFaq(lista, termo) {
  const n = (s) => String(s).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();
  // palavras de 2 letras também valem ("tv", "pe", "kg"), menos as de ligação; elas só casam como palavra inteira
  const LIGACAO = new Set(['de', 'do', 'da', 'em', 'um', 'no', 'na', 'os', 'as', 'ao', 'se', 'eu', 'ou', 'me', 'te', 'ja', 'so']);
  const palavras = n(termo).split(/[^a-z0-9]+/).filter((w) => w.length > 2 || (w.length === 2 && !LIGACAO.has(w)));
  if (!palavras.length) return lista;
  const inteira = (texto, w) => (' ' + texto.replace(/[^a-z0-9]+/g, ' ') + ' ').includes(' ' + w + ' ');
  const tem = (texto, w) => (w.length === 2 ? inteira(texto, w) : texto.includes(w));
  return lista
    .map((item) => {
      const alvo = n(item.q + ' ' + item.tags);
      const corpo = n([...item.a, ...(Array.isArray(item.mais) ? item.mais : [])].join(' '));
      let pts = 0;
      for (const w of palavras) { if (tem(alvo, w)) pts += 3; else if (tem(corpo, w)) pts += 1; }
      return { item, pts };
    })
    .filter((x) => x.pts > 0)
    .sort((a, b) => b.pts - a.pts)
    .map((x) => x.item);
}
